import { test, expect } from '@playwright/test';

test.describe('Search Suggestions Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should highlight matching part of the search term in suggestions', async ({ page }) => {
    await page.getByRole('textbox', { name: 'Search' }).fill('apple');
    await page.waitForTimeout(500); // Wait for suggestions to load

    const suggestions = await page.getByRole('listbox').locator('li').allTextContents();
    suggestions.forEach(suggestion => {
      expect(suggestion).toContain('apple');
      expect(suggestion).toMatch(/<mark>apple<\/mark>/); // Assuming highlights are wrapped in <mark> tags
    });
  });

  test('should not highlight non-matching part of the search term in suggestions', async ({ page }) => {
    await page.getByRole('textbox', { name: 'Search' }).fill('banana');
    await page.waitForTimeout(500); // Wait for suggestions to load

    const suggestions = await page.getByRole('listbox').locator('li').allTextContents();
    suggestions.forEach(suggestion => {
      expect(suggestion).not.toMatch(/<mark>[^b].*<\/mark>/); // Ensure non-matching parts are not highlighted
    });
  });
});
